// TH14 v1.00b Extra 道中波次 th14_s7_w10
// 源: st07.ecl.txt MainSub06(890-937) entry；ECir01(94-127)、ECir01_at(129-157) dependency。
// Extra(!O) 单版本；源入口帧0 = 卡帧约122（120帧开场缓冲 + 新任务首跑偏移）。
// 关卡父上下文在(0,0)，ECir01 的 REL 运动在此按世界坐标显式写出。

const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// ECir01_at 129-157：两轮；每轮取一次自机方向基准，之后每10帧发一对反向直线激光，
// 基准角每步按 dir*20deg 递增。
async sub ecir01_at(dir: int) {
    var b: angle = 0deg;
    var step: angle = 20deg;
    if dir < 0 { step = -20deg; }
    for r in 0..2 {                                  // 源 138-155：$C=1 的两轮
        // 源 141: (%ANGLE_PLAYER - pi/4) + 0.17453292*%RANDF2
        b = aim_player() - 45deg + (rand(1820) as angle);
        for i in 0..32 {                             // 源 143-152：$D=32，每10帧
            // 源 136-137: laserNew(0, 0, 128, 0, 14)、etSpeed 5；Line L=128,w=14
            // 判定宽 = 2*(14/4) = 7；lz_speed 表达源 Line 先沿角长出再平移。
            var lz: int = laser(3, $self_x, $self_y, b, 0.0fx, 7.0fx, 0, 30, 0);
            lz_speed(lz, 5.0fx, 128.0fx);
            lz = laser(3, $self_x, $self_y, b - 180deg, 0.0fx, 7.0fx, 0, 30, 0);
            lz_speed(lz, 5.0fx, 128.0fx);
            b = b + step;                            // 源 149: B += A*2pi/18
            wait(10);                                // 源 150
        }
        wait(60);                                    // 源 153
    }
}

// ECir01 94-127。dir=+1：源 enmCreate(MIRROR=0)；dir=-1：enmCreateM(MIRROR=1)。
async sub ecir01(dir: int) {
    set_invuln(65535);
    set_hurtbox(12.0fx);                             // 源 103 setHurtbox(24,24) -> r=12
    set_hitbox(8.0fx);                               // 源 104 setHitbox(16,16) -> r=8
    set_enemy_flag(ENEMY_NO_BODY, 1);                // 源 108 flagSet(15)：含0x2禁体碰位
    // 源 114 movePosRel(-192*A, 0)，父在(0,0)
    move_to(0, (dir * -192) as fx, 0.0fx, EASE_LINEAR);
    // 源 115 moveBezierRel(120, 256A,-30, 160A,128, 0,0)
    hermite_start(0, (dir * -192) as fx, (dir * 160) as fx, (dir * 256) as fx, 0.0fx, 120);
    hermite_start(1, 0.0fx, 128.0fx, -30.0fx, 0.0fx, 120);
    for k1 in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // 源 116 wait(120) 即上面120帧；源 117 flagClear(15)
    set_enemy_flag(ENEMY_NO_BODY, 0);
    // 源 119-120 moveBezierRel(120, 0,0, -220A,192, -200A,-228) + @ECir01_at(%A) async
    hermite_start(0, (dir * 160) as fx, (dir * -220) as fx, 0.0fx, (dir * -200) as fx, 120);
    hermite_start(1, 128.0fx, 192.0fx, 0.0fx, -228.0fx, 120);
    spawn ecir01_at(dir);
    for k2 in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // 源 122-125 wait(1000) 循环保活
    loop { wait(1000); }
}

// MainSub06 890-937：四批各10只，M/普通/M/普通交替；F0/F1 仅作继承槽快照，
// ECir01 不读取，但仍逐次采样 F1 以保留共享随机流消耗。
async sub wave() {
    wait(OPENING_BUFFER);                            // 源入口帧0
    wait(80);                                        // 源 896
    var f0: fx = -160.0fx;                           // 源 893
    var f1: fx = 0.0fx;
    for iA in 0..10 {                                 // 源 897-905 enmCreateM
        f0 = f0 + 32.0fx;                            // 源 900
        f1 = (rand(2048) as fx / 2048.0fx) * 32.0fx - 96.0fx;  // 源 901
        _ = spawn_enemy(0.0fx, 0.0fx, 130, 1, 1000, 0, ecir01(-1));
        wait(10);                                    // 源 903
    }
    wait(160);                                       // 源 906
    for iB in 0..10 {                                 // 源 907-915 enmCreate
        f0 = f0 + 32.0fx;
        f1 = (rand(2048) as fx / 2048.0fx) * 32.0fx - 96.0fx;
        _ = spawn_enemy(0.0fx, 0.0fx, 130, 1, 1000, 0, ecir01(1));
        wait(10);
    }
    wait(140);                                       // 源 916
    for iC in 0..10 {                                 // 源 917-925 enmCreateM
        f0 = f0 + 32.0fx;
        f1 = (rand(2048) as fx / 2048.0fx) * 32.0fx - 96.0fx;
        _ = spawn_enemy(0.0fx, 0.0fx, 130, 1, 1000, 0, ecir01(-1));
        wait(10);
    }
    wait(120);                                       // 源 926
    for iD in 0..10 {                                 // 源 927-935 enmCreate
        f0 = f0 + 32.0fx;
        f1 = (rand(2048) as fx / 2048.0fx) * 32.0fx - 96.0fx;
        _ = spawn_enemy(0.0fx, 0.0fx, 130, 1, 1000, 0, ecir01(1));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0.0fx, 0.0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
